<?php require_once 'config.php'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=db()->prepare('SELECT id,password_hash FROM customers WHERE email=?');$s->execute([strtolower(trim($_POST['email']??''))]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['customer_id']=(int)$u['id'];redirect('customer/dashboard.php');}$error='Incorrect email or password.';} page_start('Customer sign in'); if($error) echo '<div class="alert error">'.e($error).'</div>'; ?>
<form method="post" class="form panel"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn">Sign in</button><p>New customer? <a href="register.php">Create an account</a></p></form><?php page_end(); ?>
